using System;
using System.Text.RegularExpressions;

internal static class OfflineStoryboardEngine
{
    public static string Compose(string source)
    {
        string food = Read(source, "음식 :");
        string traits = Read(source, "음식 핵심 특징 :");
        if (string.IsNullOrWhiteSpace(food)) food = "랜덤 디저트";
        if (string.IsNullOrWhiteSpace(traits)) traits = "고유한 색, 질감, 형태와 맛";
        string world = "따뜻한 오후 햇살이 비치는 아늑한 판타지 베이커리의 원목 디저트 테이블";
        string fox = "same exact attached pure white nine-tailed fox, large glossy blue eyes, small black nose, pink forehead marking, cute compact body, exactly nine distinct tails";
        return $"[이번 영상]\r\n\r\n사용 모델 : VEO 3.1-LIGHT\r\n플랫폼 : TikTok\r\n화면 비율 : Vertical 9:16\r\n음식 : {food}\r\n음식 핵심 특징 : {traits}\r\n배경 : {world}\r\n\r\n[전체 변신 컨셉]\r\n첨부 기준 이미지 속 순백색 구미호가 {food}을 실제로 먹고, 음식의 색·질감·형태·물성 중 핵심 특징을 순백색 기본 정체성 위에 점진적으로 융합한다. 단순 색상 교체나 다른 여우로의 교체는 금지한다.\r\n\r\n[최종 변신 디자인]\r\n신체 : 원래 얼굴, 푸른 눈, 분홍색 이마 문양, 작고 통통한 비율을 유지한다.\r\n털 : 순백색 베이스를 유지하면서 {traits}에서 파생한 질감과 은은한 포인트를 털 끝에만 적용한다.\r\n귀 : 원래 귀 형태를 유지하고 음식 관련 작은 결정만 절제되게 추가한다.\r\n아홉 꼬리 : 정확히 9개를 각각 분리해 보이게 하며 음식의 질감과 색을 미세하게 반영한다.\r\n주변 이펙트 : 음식과 직접 관련된 소량의 입자·버블·결정만 사용하고 얼굴을 가리지 않는다.\r\n발밑 효과 : 음식 물성에 맞춰 눌림·반동·작은 파동 중 하나가 생긴다.\r\n\r\n[장면 1 — 음식 발견 / 변신 0%]\r\n이미지/첫 프레임 기준 프롬프트 : Vertical 9:16 TikTok safe area, {fox}, the fox and one detailed {food} are both visible in the center from the first frame, {world}, no transformation, no text, no logo.\r\nVEO 3.1-LIGHT 영상 프롬프트 : The fox immediately notices the same {food}, sniffs it and brings its nose close, gentle medium push-in, native audio: a small curious “뀽?” and soft ambience. Keep the same character, food, location and lighting.\r\n영상 움직임 : 즉시 음식과 구미호를 함께 보여주고 짧게 접근한다.\r\n캐릭터 행동 : 눈을 반짝이고 귀를 움직이며 킁킁 냄새를 맡는다.\r\n음식 상태 : 완전한 원래 음식, 한입 자국 없음.\r\n카메라 : eye-level medium shot, gentle push-in.\r\n캐릭터 소리 : 작은 ‘뀽?’와 킁킁.\r\n효과음 : 은은한 공간음과 발견 순간의 작은 반짝임.\r\n장면 마지막 프레임 상태 : 입이 음식 바로 앞, 변신 0%.\r\n\r\n[장면 2 — 음식 섭취 / 변신 10~20%]\r\n이미지/첫 프레임 기준 프롬프트 : Vertical 9:16, {fox}, mouth physically contacting the same {food}, a real visible bite or consumed portion, clear remaining bite mark, same table and lighting.\r\nVEO 3.1-LIGHT 영상 프롬프트 : The fox's mouth physically contacts the food and it visibly consumes a real portion of it. Show the bite, chewing and swallowing. The food remains visibly reduced. Only after swallowing, a subtle food-derived reaction begins around the mouth; close-up rack focus, native food ASMR.\r\n영상 움직임 : 실제 섭취 동작을 한 번 명확하게 보여준다.\r\n캐릭터 행동 : 한입 먹고 씹은 뒤 놀라서 입 주변 변화를 확인한다.\r\n음식 상태 : 실제 한입 자국 또는 줄어든 양을 장면 3·4까지 유지한다.\r\n변화 : 입 주변만 10~20%, 아직 완전 변신 금지.\r\n카메라 : food-to-character close-up, same camera axis.\r\n캐릭터 소리 : ‘앙!’ 뒤 만족스러운 짧은 ‘뀽~’.\r\n효과음 : 음식 질감에 맞는 실제 ASMR과 작은 마법음.\r\n장면 마지막 프레임 상태 : 첫 음식 유래 입자가 얼굴 쪽으로 이동.\r\n\r\n[장면 3 — 본격적인 변신 / 변신 40~60%]\r\n이미지/첫 프레임 기준 프롬프트 : Vertical 9:16, {fox}, same partially eaten {food} with the same bite mark, transformation wave visibly travels from mouth to face, ears, body and all nine tails.\r\nVEO 3.1-LIGHT 영상 프롬프트 : Follow the transformation wave sequentially across the fur and exactly nine separate tails. The fox looks at its paws, turns to discover the changing tails, then touches one tail; slow side tracking shot, synchronized magical shimmer and food-texture sound.\r\n신체 변화 : 음식 특성이 입 주변 → 얼굴 → 귀 → 몸통 → 다리 → 꼬리 뿌리 순서로 퍼진다.\r\n꼬리 변화 : 정확히 9개, 40~60%까지 순차 변화.\r\n장식 생성 : 음식과 직접 관련된 작은 장식만 형성 시작.\r\n주변 이펙트 : 얼굴을 가리지 않는 소량의 음식 유래 입자.\r\n발밑 효과 : 음식 물성에 맞는 짧은 반응.\r\n카메라 : 얼굴 → 앞발 → 몸통 → 9개 꼬리로 이동.\r\n캐릭터 소리 : 놀란 ‘뀽?!’ 뒤 신기해하는 작은 울음.\r\n효과음 : 연속 쉬머와 음식 질감 효과.\r\n장면 마지막 프레임 상태 : 마지막 파동이 꼬리 끝으로 향함.\r\n\r\n[장면 4 — 완전 변신 / 변신 100%]\r\n이미지/첫 프레임 기준 프롬프트 : Vertical 9:16, {fox}, fully transformed while clearly retaining original white fox identity, exactly nine separate fluffy tails fanned behind the character, food-derived details only, no text.\r\nVEO 3.1-LIGHT 영상 프롬프트 : The final wave reaches all tail tips. The fox makes one light happy jump; on landing the food-themed floor effect reacts. Pull back enough to show all nine tails, then move to its face as it raises one paw, tilts its head and blinks at camera. Native audio: happy ‘뀽!’, food-themed effect, seamless loop, no fade to black.\r\n완성된 신체 : 순백색 정체성을 유지한 음식 특성 융합 디자인.\r\n완성된 아홉 꼬리 : 정확히 9개, 부채처럼 구분되어 보임.\r\n완성된 장식 : 음식과 관련된 작고 가벼운 장식만 유지.\r\n주변 이펙트 : 적은 양의 음식 유래 입자.\r\n발밑 효과 : 착지 때 음식 물성에 맞는 짧은 반응.\r\n최종 포즈 : 꼬리를 펼치고 한쪽 앞발을 든 채 고개를 살짝 기울인다.\r\n카메라 : pull-back to nine tails, then slow face push-in.\r\n캐릭터 소리 : 기쁜 ‘뀽!’ 또는 ‘먕~’.\r\n효과음 : 완성 쉬머, 착지음, 코앞의 작은 음식 테마 효과.\r\n장면 마지막 프레임 상태 : 음식 테마 효과가 코앞에서 사라지며 첫 장면으로 루프.\r\n\r\n[BGM]\r\nbright, cute, catchy, whimsical fantasy pop instrumental. 장면 1 호기심, 장면 2 장난스러운 리듬, 장면 3 벨·플럭·쉬머 고조, 장면 4 만족스러운 절정 뒤 첫 박자로 자연스럽게 루프.\r\n\r\n[장면 연결]\r\n장면 1 → 2 : 음식에 가까이 댄 입이 그대로 실제 한입으로 이어진다.\r\n장면 2 → 3 : 삼킨 뒤 입 주변 변화가 끊기지 않고 몸과 꼬리로 퍼진다.\r\n장면 3 → 4 : 파동이 마지막 꼬리 끝에 닿으며 점프와 최종 포즈로 이어진다.\r\nprevious scene continuity must be preserved; no visual reset between scenes.\r\n\r\n[공통 캐릭터 고정 프롬프트]\r\n{fox}, consistent character model, same background, lighting and body scale.\r\n\r\n[VEO 3.1-LIGHT 공통 네거티브 프롬프트]\r\ndifferent character, wrong eye color, missing forehead marking, extra tails, fewer tails, merged tails, malformed anatomy, different food, additional food, regenerated food, missing bite mark, fake eating, no mouth-food contact, transformation before eating, instant full transformation, reset, teleportation, camera axis flip, inconsistent background, inconsistent lighting, humans, text, subtitles, logo, watermark, UI, horizontal composition, cropped face, cropped food, fade to black.";
    }
    static string Read(string s,string key){var i=s.IndexOf(key);if(i<0)return "";i+=key.Length;var e=s.IndexOf('\n',i);return s.Substring(i,(e<0?s.Length:e)-i).Trim();}
}
